import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#10
it('caches dynamic validators by schema reference', async () => {
  const registry = new ToolRegistry();
  const schemas = [
    {type: 'object', required: ['location']},
    {type: 'object', required: ['unit']},
  ];
  let current = 0;
  registry.register(
    () => ({name: 'weather', description: 'Weather', inputSchema: schemas[current]}),
    async () => 'ok'
  );

  const compile = jest.spyOn(registry['validator'], 'compile');
  expect((await registry.execute('weather', {})).result).toContain('location');
  expect(compile).toHaveBeenCalledTimes(1);
  await registry.execute('weather', {location: 'Paris'});
  current = 1;
  const second = await registry.execute('weather', {});
  await registry.execute('weather', {unit: 'C'});
  current = 0;
  await registry.execute('weather', {location: 'Paris'});
  expect(second.result).toContain('unit');
  expect(compile).toHaveBeenCalledTimes(2);
});
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#13
it('rejects an inherited required property', async () => {
  const registry = new ToolRegistry();
  const executor = jest.fn(async () => 'sunny');
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
    executor
  );
  const input = Object.create({location: 'Paris'}) as Record<string, unknown>;
  const response = await registry.execute('weather', input);
  expect(response.result).toMatch(/location.*required|required.*location/i);
  expect(executor).not.toHaveBeenCalled();
});
